import java.util.*;

class Bfs {
    // Diagnostic task: BFS distances in Java.
    static Map<String, Integer> distances(Map<String, List<String>> adj, String start) {
        Map<String, Integer> dist = new HashMap<>();
        Deque<String> queue = new ArrayDeque<>();     // a queue, not a Stack.
        dist.put(start, 0);
        queue.add(start);
        while (!queue.isEmpty()) {
            String u = queue.poll();                 // from the front.
            for (String v : adj.getOrDefault(u, List.of())) {
                if (!dist.containsKey(v)) {          // String equality via equals/hashCode.
                    dist.put(v, dist.get(u) + 1);
                    queue.add(v);
                }
            }
        }
        return dist;
    }
}
